#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — Google Calendar sync for TeamUp.
#
#   scripts/setup-google-calendar.sh             the server in .deploy.env
#   scripts/setup-google-calendar.sh .deploy.acme.env
#
# Nothing secret is written on this machine: the values go straight to the
# server's .env over ssh, on stdin, so they are not in any process list either.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

DEPLOY_ENV="${1:-.deploy.env}"
[[ -f "$DEPLOY_ENV" ]] || { printf '%s not found: it names the server (TEAMUP_DEPLOY_HOST, TEAMUP_DEPLOY_KEY).\n' "$DEPLOY_ENV" >&2; exit 1; }
# shellcheck disable=SC1090
. "$DEPLOY_ENV"
HOST="${TEAMUP_DEPLOY_HOST:?TEAMUP_DEPLOY_HOST is not set in $DEPLOY_ENV}"
SSH=(ssh -4 -o ConnectTimeout=15)
[[ -n "${TEAMUP_DEPLOY_KEY:-}" ]] && SSH+=(-i "$TEAMUP_DEPLOY_KEY")
DIR="${TEAMUP_DEPLOY_DIR:-/opt/teamup}"

banner "Google Calendar sync for TeamUp"

stage "Which TeamUp"
say "This connects Google Calendar for one TeamUp server."
note "Server: $HOST ($DIR)"
FOUND=$("${SSH[@]}" "$HOST" "grep -E '^TEAMUP_DOMAIN=' '$DIR/.env' | cut -d= -f2" 2>/dev/null || true)
ask DOMAIN "TeamUp's address, without https:// [Enter for ${FOUND:-none found}]:"
DOMAIN="${DOMAIN:-$FOUND}"
DOMAIN="${DOMAIN#https://}"; DOMAIN="${DOMAIN%%/*}"
[[ -n "$DOMAIN" ]] || { warn "an address is needed"; exit 1; }
REDIRECT="https://$DOMAIN/api/calendar/google/callback"
note "Google will send people back to: $REDIRECT"
pause

stage "Google Cloud project and Calendar API"
say "Use the Google account that runs Cognecto's Google Workspace, if it has one."
open_url "https://console.cloud.google.com/projectcreate"
step "Create a project named 'TeamUp' (or pick an existing one), and make sure it is selected at the top."
pause "Project selected? Press Enter to turn on the Calendar API."
open_url "https://console.cloud.google.com/apis/library/calendar-json.googleapis.com"
step "Click 'Enable' on Google Calendar API (it says 'Manage' if it is on already)."
pause "Done?"

stage "Consent screen"
open_url "https://console.cloud.google.com/auth/overview"
step "If asked, click 'Get started'. App name: TeamUp. Support email: yours."
step "Audience: choose 'Internal' if it is offered. That means only Cognecto's Google accounts can"
say  "  connect, and Google does not need to review the app."
note "Only 'External' offered (no Workspace)? Choose it, then under Audience add each person's"
note "Gmail address as a test user, or publish the app (Google may then ask to verify it)."
step "Contact email: yours. Agree, then Create."
step "Data Access → Add or remove scopes → tick '.../auth/calendar.events', 'openid' and"
say  "  '.../auth/userinfo.email' → Update → Save."
pause "Consent screen saved?"

stage "OAuth client"
open_url "https://console.cloud.google.com/auth/clients/create"
step "Application type: Web application. Name: TeamUp calendar."
step "Authorized redirect URIs → Add URI → paste exactly:"
say  "    $REDIRECT"
step "Click Create. A box shows the Client ID and Client secret."
ask GCAL_CLIENT_ID "Paste the Client ID:"
ask_secret GCAL_CLIENT_SECRET "Paste the Client secret (hidden):"
[[ "$GCAL_CLIENT_ID" == *.apps.googleusercontent.com ]] || warn "that does not look like a client ID (…apps.googleusercontent.com); check it"
[[ -n "$GCAL_CLIENT_SECRET" ]] || { warn "the secret is needed"; exit 1; }

stage "Save on the server"
say "Writing GCAL_CLIENT_ID, GCAL_CLIENT_SECRET and GCAL_TOKEN_KEY to $HOST:$DIR/.env."
KEEP_KEY=no
if "${SSH[@]}" "$HOST" "grep -qE '^GCAL_TOKEN_KEY=.+' '$DIR/.env'"; then
  note "A token key is there already. Keeping it keeps everybody connected."
  KEEP_KEY=yes
fi
confirm "Write these to the server now?" || { warn "nothing was written"; exit 1; }
GCAL_TOKEN_KEY=""
[[ "$KEEP_KEY" == yes ]] || GCAL_TOKEN_KEY=$(openssl rand -hex 32)
# Values arrive on stdin, one KEY=VALUE per line; an empty value is not written.
printf 'GCAL_CLIENT_ID=%s\nGCAL_CLIENT_SECRET=%s\nGCAL_TOKEN_KEY=%s\n' "$GCAL_CLIENT_ID" "$GCAL_CLIENT_SECRET" "$GCAL_TOKEN_KEY" |
  "${SSH[@]}" "$HOST" "set -e; cd '$DIR'; sudo cp .env .env.before-gcal; while IFS= read -r line; do
      key=\${line%%=*}; value=\${line#*=}; [ -n \"\$value\" ] || continue
      sudo sed -i \"/^\$key=/d\" .env; printf '%s\n' \"\$line\" | sudo tee -a .env >/dev/null
    done"
unset GCAL_CLIENT_SECRET GCAL_TOKEN_KEY
printf '  %s✓ saved%s on the server (the previous file is .env.before-gcal)\n' "$GREEN" "$RESET"
WRITTEN_ENV+=("GCAL_CLIENT_ID" "GCAL_CLIENT_SECRET" "GCAL_TOKEN_KEY (on $HOST)")
ENV_FILE="$HOST:$DIR/.env"

stage "Restart TeamUp"
warn "This restarts the TeamUp server, which drops anybody in a call for a moment."
if confirm "Restart now? (Say no if a meeting is on: the summary says how to restart later.)"; then
  "${SSH[@]}" "$HOST" "cd '$DIR' && grep -q TEAMUP_GCAL_CLIENT_ID docker-compose.prod.yml && sudo docker compose up -d teamup" \
    || { warn "the server's compose file does not pass the Google settings yet: deploy the latest main first, then run this again"; SKIPPED+=("restart TeamUp after deploying main"); }
  step "Open https://$DOMAIN/calendar: a 'Connect Google Calendar' button is there for everybody."
  pause
else
  SKIPPED+=("restart TeamUp: ssh to $HOST, cd $DIR, sudo docker compose up -d teamup")
fi

finish
